here = os.path.dirname(os.path.abspath(__file__))
with zipfile.ZipFile(io.BytesIO(base64.b64decode(DATA))) as z:
    for n in z.namelist():
        dest = os.path.join(here, n)
        if os.path.basename(n).startswith('config') and n.endswith('.json') and os.path.exists(dest): continue
        os.makedirs(os.path.dirname(dest) or here, exist_ok=True)
        open(dest, 'wb').write(z.read(n))
print('unpacked', len(z.namelist()), 'files')